# Simulate round-robin scheduling to compare average waiting time
from collections import deque

def round_robin(bursts, quantum):
    """bursts: {name: burst_time}, all arriving at t=0. Returns average waiting time."""
    remaining = dict(bursts)
    q = deque(bursts)
    t, finish = 0, {}
    while q:
        name = q.popleft()
        run = min(quantum, remaining[name])
        t += run
        remaining[name] -= run
        if remaining[name] == 0:
            finish[name] = t
        else:
            q.append(name)
    waits = [finish[n] - bursts[n] for n in bursts]   # waiting = turnaround - burst (arrival 0)
    return sum(waits) / len(waits)

print(round_robin({"A": 24, "B": 3, "C": 3}, 4))   # ~5.67
