// Node: processes vs threads. fork a child process (isolated memory) and use a worker thread (shared-capable memory)
import { fork } from "node:child_process";
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";

if (isMainThread) {
  const child = fork(new URL("./child.js", import.meta.url));      // separate process, communicates by IPC messages
  child.on("message", (m) => console.log("child says", m));

  const sab = new SharedArrayBuffer(4);                              // memory shared between threads
  const counter = new Int32Array(sab);
  const w = new Worker(new URL(import.meta.url), { workerData: sab });
  w.on("exit", () => console.log("counter =", Atomics.load(counter, 0))); // 1000 thanks to atomics
} else {
  const c = new Int32Array(workerData);
  for (let i = 0; i < 1000; i++) Atomics.add(c, 0, 1);               // atomic increment: no lost updates
  parentPort.postMessage("done");
}

# Simulate FIFO vs LRU page replacement and count faults
from collections import OrderedDict, deque

def fifo(refs, frames):
    mem, q, faults = set(), deque(), 0
    for p in refs:
        if p not in mem:
            faults += 1
            if len(mem) == frames:
                mem.discard(q.popleft())
            mem.add(p); q.append(p)
    return faults

def lru(refs, frames):
    mem, faults = OrderedDict(), 0
    for p in refs:
        if p in mem:
            mem.move_to_end(p)               # most recently used goes to the end
        else:
            faults += 1
            if len(mem) == frames:
                mem.popitem(last=False)      # evict least recently used
            mem[p] = True
    return faults

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]
print(fifo(refs, 3), fifo(refs, 4))   # 9, 10  -> Belady's anomaly
print(lru(refs, 3), lru(refs, 4))     # 10, 8  -> more frames never hurt LRU

// Address translation arithmetic for 4 KiB pages
#include <cstdint>
#include <iostream>
int main() {
    const uint64_t PAGE = 4096;                  // 2^12
    uint64_t va = 0x1A2B3C;
    uint64_t offset = va & (PAGE - 1);           // low 12 bits
    uint64_t vpn = va >> 12;                     // virtual page number
    uint64_t frame = 0x7F;                       // pretend the page table said so
    uint64_t pa = (frame << 12) | offset;
    std::cout << std::hex << "vpn=" << vpn << " offset=" << offset << " pa=" << pa << "\n";  // pa=7fb3c
}

// Deadlock-free transfer using a global lock order, plus a producer-consumer with a blocking queue
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

class Account {
    final long id; long balance; final ReentrantLock lock = new ReentrantLock();
    Account(long id, long balance) { this.id = id; this.balance = balance; }
}

class Bank {
    void transfer(Account from, Account to, long amount) {
        Account first = from.id < to.id ? from : to;     // always lock the smaller id first
        Account second = first == from ? to : from;
        first.lock.lock();
        try {
            second.lock.lock();
            try {
                if (from.balance < amount) throw new IllegalStateException("insufficient funds");
                from.balance -= amount;
                to.balance += amount;
            } finally { second.lock.unlock(); }
        } finally { first.lock.unlock(); }
    }
}

