// Go: protect shared state with a mutex, or avoid sharing with channels
package main

import ("fmt"; "sync")

type Counter struct { mu sync.Mutex; n int }
func (c *Counter) Inc() { c.mu.Lock(); defer c.mu.Unlock(); c.n++ } // defer guarantees unlock

func main() {
    var c Counter
    var wg sync.WaitGroup
    for i := 0; i < 1000; i++ { wg.Add(1); go func() { defer wg.Done(); c.Inc() }() }
    wg.Wait()
    fmt.Println(c.n) // always 1000; try removing the mutex and run with `go run -race`

    // Message passing instead of shared memory: a worker owns the data
    jobs := make(chan int, 10); results := make(chan int, 10)
    go func() { for j := range jobs { results <- j * j } ; close(results) }()
    for i := 1; i <= 3; i++ { jobs <- i }
    close(jobs)
    for r := range results { fmt.Println(r) }
}
